(()=>{
 'use strict';
 const E=Tournament,R=CarRoster,H=TournamentHistory,KEY='autos-bl-v1',DRAFT='autos-bl-draft-v1';
 const $=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let state=null,view='play',detail=null,busy=false,toastTimer,storageFailed=false,historyEntry=null,historyCar=null,historyRaw,historyCache=H.empty(),historyStats=[],historyError='';
 try{const saved=localStorage.getItem(KEY);if(saved)state=E.validate(JSON.parse(saved));}catch(e){storageFailed=true;setTimeout(()=>toast('A korábbi mentés nem tölthető be. Ha van letöltött mentésed, töltsd be.'),500);}
 const byId=id=>state.cars.find(c=>c.id===id),name=id=>esc(byId(id).name),carNo=id=>String(Number(id.slice(1))).padStart(2,'0');
 const clone=x=>JSON.parse(JSON.stringify(x));
 function historyData(){try{const raw=localStorage.getItem(H.KEY);if(raw!==historyRaw){const data=raw?H.validate(JSON.parse(raw)):H.empty();historyStats=H.aggregate(data);historyCache=data;historyRaw=raw;historyError='';}return historyCache;}catch(e){historyError='Az előzmények nem tölthetők be: '+e.message;return historyCache;}}
 function priorCar(carName){historyData();return historyStats.find(c=>c.key===H.carKey(carName));}
 function dateLabel(value){const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleDateString('hu-HU',{year:'numeric',month:'2-digit',day:'2-digit'}):'Ismeretlen dátum';}
 function archiveTitle(){const existing=historyData().tournaments.find(e=>H.identity(e.state)===H.identity(state));return $('tournamentTitle')?.value.trim()||existing?.title||'Bajnokság '+(historyData().tournaments.length+1);}
 function archiveCurrent(){try{const entry=H.save(localStorage,state,archiveTitle());historyRaw=undefined;historyData();render();toast('A torna elmentve az Előzmények közé.');return entry;}catch(e){toast('A torna nem menthető: '+e.message);return null;}}
 function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
 function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));if(!state||state.seed!==next.seed||next.cars.some((c,i)=>c.name!==state.cars[i].name||c.pot!==state.cars[i].pot))R.save(localStorage,R.fromTournament(next).pots);storageFailed=false;}catch(e){storageFailed=true;toast('A böngésző nem tud menteni. A letöltés gombokkal őrizd meg az autókat és a játékot.');}state=next;updateStorage();}
 function savedRoster(){try{return R.load(localStorage);}catch(e){return null;}}
 function currentPots(){if(state)return R.fromTournament(state).pots;const form=$('setupForm');return Array.from({length:4},(_,k)=>Array.from({length:8},(_,i)=>form.elements['car-'+k+'-'+i].value.trim()));}
 function saveRoster(){try{const data=R.save(localStorage,currentPots());if(!state)$('rosterStatus').textContent='✓ 32 autó és a négy kalap elmentve. A következő bajnoksághoz is megmarad.';if($('setupLoadRoster'))$('setupLoadRoster').disabled=false;toast('Az autók és a kalapbeosztás elmentve.');return data;}catch(e){toast('Az autólista nem menthető: '+e.message);return null;}}
 function updateStorage(){const prefix=storageFailed?'Az automatikus mentés nem sikerült. Töltsd le a mentést! ':'A játék, az autólista és a tornaelőzmények ezen az eszközön, ebben a böngészőben mentődnek. ';$('storageNote').textContent=prefix+'Másik eszközre a letöltött mentést töltsd be.';}
 function ask(title,message,label='Rendben'){return new Promise(resolve=>{const d=$('confirmDialog');$('dialogTitle').textContent=title;$('dialogText').textContent=message;$('dialogOK').textContent=label;let decided=false;const finish=v=>{if(decided)return;decided=true;d.close();resolve(v);};$('dialogOK').onclick=()=>finish(true);$('dialogCancel').onclick=()=>finish(false);d.oncancel=e=>{e.preventDefault();finish(false);};d.showModal();});}
 function rules(){return '<details class="rules"><summary>Versenyszabályok és pontazonosság</summary><ul><li>4 kalap, kalaponként 8 autó. Minden autó 8 különböző ellenféllel játszik, kalaponként kettővel, a saját kalapból is.</li><li>Győzelem: 2 pont. Vereség: 0 pont. Az alapszakasz 8 forduló, fordulónként 16 meccs.</li><li>1–8.: közvetlen nyolcaddöntő. 9–24.: playoff. 25–32.: kiesés.</li><li>Playoff: 9–24., 10–23., 11–22., 12–21., 13–20., 14–19., 15–18., 16–17. Egy győzelem dönt.</li><li>A nyolcaddöntőben a 16 autó teljesen szabad új sorsolást kap. Egy győzelem dönt. Innen rögzített az ág; korábbi ellenfelek újra találkozhatnak.</li><li>Negyeddöntő: 2 győzelemig. Elődöntő: 3 győzelemig. Döntő: 5 győzelemig.</li><li>Pontazonosságnál: ellenfelek összpontszáma → legyőzött ellenfelek összpontszáma → az induláskor kisorsolt, rögzített sorrend. A kalap nem ad előnyt.</li><li>Az alapszakasz közben a helyezések ideiglenesek. Egy ugratás holtversenye esetén ismételjetek, majd jelöljétek a győztest.</li></ul></details>';}
 function setup(){
  const roster=savedRoster();let draft=roster?roster.pots:Array.from({length:4},()=>Array(8).fill(''));try{const d=JSON.parse(localStorage.getItem(DRAFT));if(Array.isArray(d)&&d.length===4&&d.every(p=>Array.isArray(p)&&p.length===8&&p.every(n=>typeof n==='string'))&&d.flat().some(n=>n.trim()))draft=d;}catch(e){}
  $('main').innerHTML='<div class="intro"><div><span class="eyebrow">INDULHAT A BAJNOKSÁG</span><h2>Melyik autó lesz a bajnok?</h2><p>Írd be az autókat a négy kalapba. Mi sorsolunk és számolunk; játék közben csak a győztesre kell rányomnotok.</p></div><span class="badge">Mobilon is kényelmes</span></div><form id="setupForm"><div class="pots">'+draft.map((p,k)=>'<section class="pot"><div class="pot-title"><h3><span class="pot-no">'+(k+1)+'</span>'+['Legjobb kalap','Második kalap','Harmadik kalap','Negyedik kalap'][k]+'</h3><small id="potCount'+k+'">0 / 8</small></div>'+p.map((n,i)=>'<label class="car-input"><span>'+String(k*8+i+1).padStart(2,'0')+'</span><input autocomplete="off" aria-label="'+(k+1)+'. kalap, '+(i+1)+'. autó" maxlength="80" required name="car-'+k+'-'+i+'" value="'+esc(n||'')+'" placeholder="'+(i===0?'Pl. piros Ferrari':'Autó neve vagy beceneve')+'"></label>').join('')+'</section>').join('')+'</div><p id="setupError" class="error" role="alert"></p><div class="start-row"><p id="totalCount">0 / 32 autó megadva</p><button type="submit" class="yellow">Sorsolás és kezdés ↗</button></div></form>'+rules();
  const form=$('setupForm');const read=()=>currentPots();
  const rosterPanel=document.createElement('section');rosterPanel.className='roster-panel';rosterPanel.innerHTML='<div><strong>Az autók megmaradnak a következő játékra</strong><p id="rosterStatus">'+(roster?'✓ Van elmentett autólistátok, a kalapbeosztással együtt.':'A teljes autólista a bajnokság indításakor automatikusan elmentődik. Előbb is elmentheted.')+'</p></div><div class="roster-actions"><button type="button" id="setupSaveRoster">Autólista mentése</button><button type="button" id="setupLoadRoster" '+(!roster?'disabled':'')+'>Mentett autók betöltése</button></div>';form.before(rosterPanel);
  $('setupSaveRoster').onclick=()=>{if(saveRoster())$('setupLoadRoster').disabled=false;};
  $('setupLoadRoster').onclick=()=>{const saved=savedRoster();if(!saved)return;saved.pots.forEach((p,k)=>p.forEach((n,i)=>form.elements['car-'+k+'-'+i].value=n));counts();$('rosterStatus').textContent='✓ A mentett 32 autó betöltve. Indíthatjátok az új sorsolást.';};
  function counts(){const d=read();let total=0;d.forEach((p,k)=>{const n=p.filter(Boolean).length;total+=n;$('potCount'+k).textContent=n+' / 8';});$('totalCount').textContent=total+' / 32 autó megadva';try{localStorage.setItem(DRAFT,JSON.stringify(d));}catch(e){}}
  form.addEventListener('input',counts);counts();
  for(let k=0;k<4;k++)for(let i=0;i<8;i++)form.elements['car-'+k+'-'+i].addEventListener('paste',e=>{const lines=e.clipboardData.getData('text').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(lines.length<=1)return;e.preventDefault();lines.slice(0,8-i).forEach((s,j)=>form.elements['car-'+k+'-'+(i+j)].value=s.slice(0,80));counts();});
  form.onsubmit=e=>{e.preventDefault();try{const seed=crypto.getRandomValues(new Uint32Array(1))[0];persist(E.create(read(),seed));view='play';render();window.scrollTo({top:0,behavior:'smooth'});toast('Kész a sorsolás. Jöhet az első meccs!');}catch(err){$('setupError').textContent=err.message;}};
 }
 function nav(){const tabs=state?[['play','Játék'],['table','Tabella'],['schedule','Meccsek'],['bracket','Kieséses ág'],['history','Előzmények']]:[['play','Új bajnokság'],['history','Előzmények']];return '<nav class="tabs" aria-label="Versenynézetek">'+tabs.map(([v,label])=>'<button data-view="'+v+'" class="'+(view===v?'selected':'')+'" aria-current="'+(view===v?'page':'false')+'">'+label+'</button>').join('')+'</nav>';}
 function carIcon(p){return '<svg viewBox="0 0 120 45" aria-hidden="true"><path fill="'+['#087558','#277eac','#d19e19','#9a64ac'][p-1]+'" d="M8 26h12l14-16h41l17 16h17v13H8z"/><path fill="#d9e8ee" d="M39 14h15v12H29zm20 0h14l12 12H59z"/><circle fill="#102332" cx="30" cy="36" r="8"/><circle fill="#102332" cx="91" cy="36" r="8"/><circle fill="#e0e7ea" cx="30" cy="36" r="3"/><circle fill="#e0e7ea" cx="91" cy="36" r="3"/></svg>';}
 function winnerButton(id){const c=byId(id),prior=priorCar(c.name);return '<button class="car-button" data-winner="'+id+'" aria-label="'+esc(c.name)+' nyert"><span class="car-id">'+carNo(id)+' • '+c.pot+'. KALAP</span>'+carIcon(c.pot)+'<span class="car-name">'+esc(c.name)+'</span>'+(prior?'<span class="car-prior">Korábban: '+prior.tournaments+' torna · '+prior.titles+' bajnoki cím</span>':'')+'<span class="win-label">Ez az autó nyert ✓</span></button>';}
 function table(data,compact=false){return '<div class="legend"><span class="green">1–8. közvetlen továbbjutás</span><span class="gold">9–24. playoff</span><span>25–32. kiesés</span></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Autó</th><th title="Kalap">K</th><th title="Lejátszott meccs">M</th><th title="Győzelem">Gy</th><th title="Vereség">V</th><th>Pont</th>'+(!compact?'<th title="Ellenfelek összpontszáma">Ellenfélpont</th><th title="Legyőzött ellenfelek összpontszáma">Legyőzöttpont</th><th title="Előre kisorsolt holtversenysorrend">Sorshely</th>':'')+'</tr></thead><tbody>'+data.table.map(c=>'<tr class="'+(c.rank<=8?'direct':c.rank<=24?'playoff':'out')+(c.rank===9||c.rank===25?' divider':'')+'"><td class="rank-cell">'+c.rank+'</td><td><button class="table-name" data-car="'+c.id+'">'+esc(c.name)+'</button></td><td>'+c.pot+'</td><td>'+c.played+'</td><td>'+c.won+'</td><td>'+c.lost+'</td><td class="points">'+c.points+'</td>'+(!compact?'<td>'+c.sos+'</td><td>'+c.sov+'</td><td>'+(c.lot+1)+'</td>':'')+'</tr>').join('')+'</tbody></table></div>';}
 function play(data){
  const s=data.current,t=data.match,done=s.ties.filter(x=>E.winner(x,s.need)).length,wonGames=state.events.filter(e=>e.type==='win').length;
  let html='<div class="match-top"><div><span class="eyebrow">'+(s.id==='league'?'ALAPSZAKASZ • '+(t?t.round:8)+'. FORDULÓ':'KIESÉSES SZAKASZ')+'</span><h2>'+s.name+'</h2></div><span class="count">'+done+' / '+s.ties.length+' '+(s.id==='league'?'meccs':'párharc')+'</span></div><div class="progress"><span style="width:'+done/s.ties.length*100+'%"></span></div>';
  if(t){const a=t.wins.filter(w=>w===t.a).length,b=t.wins.length-a;html+='<section class="match-panel"><p class="hint">'+(s.id==='league'?'A forduló '+t.number+'. meccse • Ki nyert?':s.need===1?'Ki jut tovább? Válaszd ki a győztest.':'A párharc '+(t.wins.length+1)+'. meccse • Ki nyert?')+'</p><div class="versus">'+winnerButton(t.a)+'<span class="vs">VS</span>'+winnerButton(t.b)+'</div>'+(s.need>1?'<div class="series"><span>'+s.need+' győzelemig</span><strong>'+a+' – '+b+'</strong><span>Párharc állása</span></div>':'')+'</section>';
   const index=s.ties.indexOf(t),next=s.ties[index+1];html+='<div class="actions"><button id="undoButton" '+(!state.events.some(e=>e.type==='win')?'disabled':'')+'>↶ Utolsó eredmény vissza</button><p class="next-up">'+(s.need>1?'A párharc győztese automatikusan továbbjut.':next?'Utána: '+name(next.a)+' – '+name(next.b):'Ez a szakasz utolsó meccse.')+'</p></div>';
  }else if(data.champion){const saved=historyData().tournaments.find(e=>H.identity(e.state)===H.identity(state));html+='<section class="stage-end"><div class="trophy" aria-hidden="true">🏆</div><span class="eyebrow">A BAJNOK</span><h2>'+name(data.champion)+'</h2><p>Döntő: '+data.current.ties[0].wins.filter(w=>w===data.current.ties[0].a).length+' – '+data.current.ties[0].wins.filter(w=>w===data.current.ties[0].b).length+'<br>'+wonGames+' meccs után megvan a győztes!</p><label class="tournament-label">A torna neve<input id="tournamentTitle" maxlength="80" value="'+esc(saved?.title||archiveTitle())+'"></label><button id="saveChampion" class="yellow">'+(saved?'Mentett torna frissítése':'Torna elmentése az előzményekbe')+'</button>'+(saved?'<p class="archive-saved">✓ Ez a torna szerepel az előzmények között.</p><button data-history-entry="'+esc(saved.id)+'">Elmentett torna megnyitása</button>':'')+'<div class="champion-actions"><button id="downloadChampion">Torna letöltése</button><button id="undoButton">↶ Utolsó eredmény vissza</button></div><button id="restartChampion" class="primary roster-restart">Új bajnokság ezekkel az autókkal ↗</button><p class="note">Új bajnokság indításakor ezt a lezárt tornát automatikusan elmentjük az előzmények közé.</p></section>';
  }else{
   const transitions={league:['Alapszakasz kész!','Az első nyolc közvetlenül továbbjut. A 9–24. helyezett most playoffot játszik.','Playoff indítása'],playoff:['Megvan a legjobb 16!','A playoff nyolc győztese csatlakozik az első nyolchoz. Most újrasorsoljuk a teljes mezőnyt.','Nyolcaddöntő sorsolása'],r16:['Jöhet a negyeddöntő!','Nyolc autó maradt. Mostantól két győzelem kell a továbbjutáshoz.','Negyeddöntő indítása'],qf:['Négy autó a bajnoki címért.','Az elődöntős párharcok három győzelemig tartanak.','Elődöntő indítása'],sf:['Kezdődhet a döntő!','Két autó maradt. Az lesz a bajnok, aki előbb szerez öt győzelmet.','Döntő indítása']};const [title,description,button]=transitions[s.id];html+='<section class="stage-end"><span class="eyebrow">SZAKASZ LEZÁRVA</span><h2>'+title+'</h2><p>'+description+'</p><button id="advanceButton" class="yellow">'+button+' ↗</button><div style="margin-top:18px"><button id="undoButton">↶ Utolsó eredmény vissza</button></div></section>';
   if(s.id==='league')html+='<h3 style="margin-top:28px">Végleges alapszakasz-tabella</h3>'+table(data,true);
  }
  const last=state.events.findLast(e=>e.type==='win');if(last){const prev=data.stages.find(x=>x.id===last.stage),tie=prev.ties.find(x=>x.id===last.tie);html+='<p class="last-result">Legutóbb: '+name(last.winner)+' nyert '+name(last.winner===tie.a?tie.b:tie.a)+' ellen.</p>';}
  return html;
 }
 function scheduleView(data){
  let html='<div class="intro"><div><span class="eyebrow">TELJES MENETREND</span><h2>Meccsek és eredmények</h2><p>A sorsolás rögzített. Nyisd le a fordulót, hogy lásd a párosításokat.</p></div></div>';
  for(let r=1;r<=8;r++){const matches=data.stages[0].ties.filter(t=>t.round===r),n=matches.filter(t=>t.wins.length).length;html+='<details class="round" '+(data.current.id==='league'&&data.match?.round===r?'open':'')+'><summary><span>'+r+'. forduló</span><span>'+n+' / 16</span></summary>'+matches.map(t=>gameRow(t,'league',1)).join('')+'</details>';}
  for(const s of data.stages.slice(1))html+='<details class="round" '+(s===data.current?'open':'')+'><summary>'+s.name+'<span>'+s.need+' győzelemig</span></summary>'+s.ties.map(t=>gameRow(t,s.id,s.need)).join('')+'</details>';
  return html+'<p class="note">Javításkor a kiválasztott eredménytől visszalépünk: az utána bevitt eredmények és későbbi sorsolások törlődnek, hogy a továbbjutók mindig helyesek legyenek.</p>';
 }
 function gameRow(t,stage,need){const w=E.winner(t,need);let fix='';if(t.wins.length){const event=state.events.findIndex(e=>e.type==='win'&&e.stage===stage&&e.tie===t.id);fix='<button class="fix" data-edit="'+event+'">Javítás</button>';}else fix='<span class="pending">Még nincs eredmény</span>';return '<div class="game-row"><span class="muted">'+(t.number||'')+'</span><span class="'+(w===t.a?'won':'')+'">'+name(t.a)+(need>1?' · '+t.wins.filter(x=>x===t.a).length:'')+'</span><span class="'+(w===t.b?'won':'')+'">'+name(t.b)+(need>1?' · '+t.wins.filter(x=>x===t.b).length:'')+'</span>'+fix+'</div>';}
 function bracket(data){return '<div class="intro"><div><span class="eyebrow">ÚT A BAJNOKI CÍMIG</span><h2>Kieséses ág</h2><p>A nyolcaddöntő sorsolása után az ág rögzített. Minden győztes automatikusan a helyére kerül.</p></div></div><div class="bracket">'+E.SPEC.slice(1).map(([id,title,need])=>{const s=data.stages.find(x=>x.id===id);return '<section class="bracket-stage"><h3>'+title+'<small>'+need+' győzelemig</small></h3>'+(s?s.ties.map(t=>{const win=E.winner(t,need);return '<div class="tie-card '+(data.match?.id===t.id?'active':'')+'"><div class="tie-line '+(win===t.a?'won':'')+'"><span>'+name(t.a)+'</span><strong>'+t.wins.filter(w=>w===t.a).length+'</strong></div><div class="tie-line '+(win===t.b?'won':'')+'"><span>'+name(t.b)+'</span><strong>'+t.wins.filter(w=>w===t.b).length+'</strong></div></div>';}).join(''):'<div class="placeholder">'+(id==='playoff'?'Az alapszakasz végén kialakuló 9–24. helyezettek.':id==='r16'?'Az első nyolc és a playoff győztesei. Új sorsolás.':'Az előző szakasz győztesei.')+'</div>')+'</section>';}).join('')+'</div>';}
 function carDetail(data){const row=data.table.find(c=>c.id===detail);return '<button id="backTable" class="quiet">← Vissza a tabellához</button><section class="car-detail"><span class="eyebrow">'+carNo(detail)+' • '+row.pot+'. KALAP</span><h2>'+name(detail)+'</h2><p>'+row.rank+'. hely • '+row.points+' pont • '+row.won+' győzelem / '+row.lost+' vereség</p>'+(priorCar(row.name)?'<p class="note">Korábban: '+priorCar(row.name).tournaments+' torna · '+priorCar(row.name).titles+' bajnoki cím · '+priorCar(row.name).wins+' győzelem</p><button data-history-car="'+esc(H.carKey(row.name))+'">Korábbi szereplések megnyitása</button>':'')+'<h3 style="margin-top:24px">Alapszakasz-mérkőzések</h3><ul>'+data.stages[0].ties.filter(t=>t.a===detail||t.b===detail).map(t=>{const other=t.a===detail?t.b:t.a;return '<li><span>'+t.round+'. forduló · '+name(other)+'</span><strong style="color:'+(t.wins[0]===detail?'var(--green)':'inherit')+'">'+(!t.wins.length?'Hátravan':t.wins[0]===detail?'Győzelem':'Vereség')+'</strong></li>';}).join('')+'</ul></section>';}
 function historyView(){const library=historyData();if(historyEntry){const entry=library.tournaments.find(e=>e.id===historyEntry);if(entry)return archivedTournament(entry);historyEntry=null;}if(historyCar)return historicCar(historyCar);
  const entries=library.tournaments.slice().sort((a,b)=>Date.parse(b.savedAt)-Date.parse(a.savedAt));
  return '<div class="intro"><div><span class="eyebrow">MINDEN TORNA MEGMARAD</span><h2>Tornaelőzmények</h2><p>A lezárt bajnokságok és az autók korábbi eredményei. Ugyanazt az autót minden tornán ugyanazzal a névvel nevezd.</p></div><button id="historyBackup" '+(!entries.length?'disabled':'')+'>Előzmények letöltése</button></div>'+(historyError?'<p class="error" role="alert">'+esc(historyError)+'</p>':'')+(!entries.length?'<section class="stage-end"><h3>Még nincs elmentett torna.</h3><p>A döntő végén nyomd meg a „Torna elmentése az előzményekbe” gombot. Az új bajnokság indítása is automatikusan elmenti az előző, befejezett tornát.</p><button data-view="play" class="primary">'+(state?'Vissza a játékhoz':'Bajnokság indítása')+'</button></section>':'<div class="stats"><div class="stat"><strong>'+entries.length+'</strong><span>Elmentett torna</span></div><div class="stat"><strong>'+historyStats.length+'</strong><span>Versenyző autó</span></div><div class="stat"><strong>'+entries.reduce((n,e)=>n+e.state.events.filter(x=>x.type==='win').length,0)+'</strong><span>Lejátszott meccs</span></div></div><h3>Az autók összesített eredményei</h3><div class="table-wrap"><table><thead><tr><th>#</th><th>Autó</th><th>Torna</th><th title="Bajnoki cím">Cím</th><th title="Nyolcaddöntőbe jutás">16-ba jutott</th><th>Gy</th><th>V</th><th>Győzelem %</th><th>Legjobb eredmény</th></tr></thead><tbody>'+historyStats.map((c,i)=>'<tr><td>'+(i+1)+'</td><td><button class="table-name" data-history-car="'+esc(c.key)+'">'+esc(c.name)+'</button></td><td>'+c.tournaments+'</td><td class="points">'+c.titles+'</td><td>'+c.roundOf16+'</td><td>'+c.wins+'</td><td>'+c.losses+'</td><td>'+c.winRate+'%</td><td>'+c.bestResult+'</td></tr>').join('')+'</tbody></table></div><p class="note">A győzelmek és vereségek minden ugratást tartalmaznak, a kieséses párharcokat is. Sorrend: bajnoki címek, döntős szereplések, győzelmek, győzelmi arány.</p><h3 style="margin-top:28px">Korábbi bajnokságok</h3><div class="history-grid">'+entries.map(entry=>{const summary=H.summary(entry),runner=entry.state.cars.find(c=>c.id===summary.runnerUp);return '<button class="history-card" data-history-entry="'+esc(entry.id)+'"><span class="eyebrow">'+dateLabel(entry.savedAt)+' • '+summary.games+' MECCS</span><strong>'+esc(entry.title)+'</strong><span class="history-champion">🏆 '+esc(summary.championName)+'</span><span class="note">Döntős: '+esc(runner.name)+' · '+summary.score+'</span><span class="history-link">Tabella és eredmények →</span></button>';}).join('')+'</div>')+'<p class="note">Az előzmények ebben a böngészőben maradnak meg. Az összes torna egy közös mentésként letölthető, és másik eszközön visszatölthető.</p>';
 }
 function historicCar(key){historyData();const car=historyStats.find(c=>c.key===key);if(!car){historyCar=null;return historyView();}return '<button id="backHistory" class="quiet">← Vissza az előzményekhez</button><section class="car-detail"><span class="eyebrow">AZ AUTÓ TÖRTÉNETE</span><h2>'+esc(car.name)+'</h2><div class="stats"><div class="stat"><strong>'+car.tournaments+'</strong><span>Torna</span></div><div class="stat"><strong>'+car.titles+'</strong><span>Bajnoki cím</span></div><div class="stat"><strong>'+car.finals+'</strong><span>Döntős szereplés</span></div><div class="stat"><strong>'+car.winRate+'%</strong><span>Győzelmi arány</span></div></div><p>'+car.wins+' győzelem · '+car.losses+' vereség · '+car.roundOf16+' alkalommal a legjobb 16-ban</p><h3>Szereplések tornánként</h3><div class="table-wrap"><table><thead><tr><th>Dátum</th><th>Torna</th><th>Eredmény</th><th>Alapszakasz</th><th>Pont</th><th>Gy</th><th>V</th></tr></thead><tbody>'+car.appearances.map(a=>'<tr><td>'+dateLabel(a.date)+'</td><td><button class="table-name" data-history-entry="'+esc(a.entryId)+'">'+esc(a.title)+'</button></td><td>'+a.result+'</td><td>'+a.rank+'. hely</td><td>'+a.points+'</td><td>'+a.wins+'</td><td>'+a.losses+'</td></tr>').join('')+'</tbody></table></div></section>';}
 function archivedTournament(entry){const summary=H.summary(entry),cars=Object.fromEntries(entry.state.cars.map(c=>[c.id,c])),rows=summary.rows.slice().sort((a,b)=>b.level-a.level||a.rank-b.rank);
  return '<button id="backHistory" class="quiet">← Vissza az előzményekhez</button><div class="intro"><div><span class="eyebrow">ELMENTETT TORNA • '+dateLabel(entry.savedAt)+'</span><h2>'+esc(entry.title)+'</h2><p>🏆 Bajnok: <strong>'+esc(summary.championName)+'</strong> · '+summary.games+' meccs</p></div><button id="downloadArchived">Torna letöltése</button></div><h3>Ki meddig jutott?</h3><div class="table-wrap"><table><thead><tr><th>#</th><th>Autó</th><th>Eredmény</th><th>Alapszakasz</th><th>Pont</th><th>Gy</th><th>V</th></tr></thead><tbody>'+rows.map((c,i)=>'<tr><td>'+(i+1)+'</td><td><button class="table-name" data-history-car="'+esc(H.carKey(c.name))+'">'+esc(c.name)+'</button></td><td class="'+(c.level===6?'archive-saved':'')+'">'+c.result+'</td><td>'+c.rank+'. hely</td><td>'+c.points+'</td><td>'+c.wins+'</td><td>'+c.losses+'</td></tr>').join('')+'</tbody></table></div><p class="note">A # oszlop megjelenítési sorrend: elért szakasz, azon belül alapszakasz-helyezés. Azonos szakaszban kieső autók között nincs utólagos helyosztó.</p><h3 style="margin-top:28px">Teljes alapszakasz-tabella</h3><div class="table-wrap"><table><thead><tr><th>#</th><th>Autó</th><th>Kalap</th><th>M</th><th>Gy</th><th>V</th><th>Pont</th></tr></thead><tbody>'+summary.data.table.map(c=>'<tr><td>'+c.rank+'</td><td>'+esc(c.name)+'</td><td>'+c.pot+'</td><td>'+c.played+'</td><td>'+c.won+'</td><td>'+c.lost+'</td><td class="points">'+c.points+'</td></tr>').join('')+'</tbody></table></div><h3 style="margin-top:28px">Minden mérkőzés és párharc</h3>'+summary.data.stages.map(s=>'<details class="round" '+(s.id==='final'?'open':'')+'><summary>'+s.name+'<span>'+s.ties.length+' '+(s.id==='league'?'meccs':'párharc')+'</span></summary>'+s.ties.map(t=>{const w=E.winner(t,s.need);return '<div class="game-row archive-game"><span class="muted">'+(t.round?t.round+'. f.':'')+'</span><span class="'+(w===t.a?'won':'')+'">'+esc(cars[t.a].name)+'</span><span class="'+(w===t.b?'won':'')+'">'+esc(cars[t.b].name)+'</span><strong>'+t.wins.filter(x=>x===t.a).length+'–'+t.wins.filter(x=>x===t.b).length+'</strong></div>'+(s.need>1?'<p class="tie-winners">A meccsek győztesei: '+t.wins.map(x=>esc(cars[x].name)).join(' → ')+'</p>':'');}).join('')+'</details>').join('');
 }
 function render(){updateStorage();['exportButton','copyButton'].forEach(id=>$(id).disabled=!state);$('newButton').disabled=!state;['saveRosterButton','exportRosterButton'].forEach(id=>$(id).disabled=!state&&view==='history');$('exportHistoryButton').disabled=!historyData().tournaments.length;if(view==='history'){$('main').innerHTML=nav()+historyView();bind();return;}if(!state){view='play';setup();$('main').insertAdjacentHTML('afterbegin',nav());bind();return;}const data=E.derive(state);let content;if(detail)content=carDetail(data);else if(view==='play')content=play(data);else if(view==='table')content='<span class="eyebrow">'+(E.complete(data.stages[0])?'VÉGLEGES ALAPSZAKASZ-TABELLA':'ÉLŐ ÁLLÁS • IDEIGLENES HELYEZÉSEK')+'</span><h2>Tabella</h2>'+table(data)+'<p class="note">M: meccs · Gy: győzelem · V: vereség. Pontazonosságnál a nagyobb ellenfélpont, majd a nagyobb legyőzöttpont, végül a kisebb sorshely dönt. Egy autó nevére koppintva láthatod az ellenfeleit.</p>'+rules();else if(view==='schedule')content=scheduleView(data);else content=bracket(data);$('main').innerHTML=nav()+content;bind();}
 function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;detail=null;historyEntry=null;historyCar=null;render();});document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>{detail=b.dataset.car;render();window.scrollTo({top:0,behavior:'smooth'});});if($('backTable'))$('backTable').onclick=()=>{detail=null;render();};document.querySelectorAll('[data-winner]').forEach(b=>b.onclick=()=>record(b.dataset.winner));if($('advanceButton'))$('advanceButton').onclick=()=>{if(busy)return;const next=clone(state);next.events.push({type:'advance'});persist(next);render();window.scrollTo({top:0,behavior:'smooth'});};if($('undoButton'))$('undoButton').onclick=undo;if($('saveChampion'))$('saveChampion').onclick=archiveCurrent;if($('downloadChampion'))$('downloadChampion').onclick=download;if($('restartChampion'))$('restartChampion').onclick=()=>newTournament(currentPots());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(Number(b.dataset.edit)));document.querySelectorAll('[data-history-entry]').forEach(b=>b.onclick=()=>{view='history';historyEntry=b.dataset.historyEntry;historyCar=null;detail=null;render();window.scrollTo({top:0,behavior:'smooth'});});document.querySelectorAll('[data-history-car]').forEach(b=>b.onclick=()=>{view='history';historyCar=b.dataset.historyCar;historyEntry=null;detail=null;render();window.scrollTo({top:0,behavior:'smooth'});});if($('backHistory'))$('backHistory').onclick=()=>{historyEntry=null;historyCar=null;render();};if($('historyBackup'))$('historyBackup').onclick=downloadHistory;if($('downloadArchived'))$('downloadArchived').onclick=()=>{const e=historyData().tournaments.find(e=>e.id===historyEntry);if(e)downloadJSON(e.state,'autos-bl-torna-'+e.id+'.json');};}
 function record(winner){if(busy)return;busy=true;const data=E.derive(state),t=data.match;if(!t){busy=false;return;}const next=clone(state);next.events.push({type:'win',stage:data.current.id,tie:t.id,winner});persist(next);render();document.querySelectorAll('[data-winner]').forEach(b=>b.disabled=true);setTimeout(()=>{busy=false;document.querySelectorAll('[data-winner]').forEach(b=>b.disabled=false);},450);}
 function undo(){if(busy)return;const idx=state.events.findLastIndex(e=>e.type==='win');if(idx<0)return;const next=clone(state);next.events=next.events.slice(0,idx);persist(next);view='play';detail=null;render();toast('Az utolsó eredményt visszavontuk.');}
 async function edit(index){if(!await ask('Eredmény javítása','Visszalépünk ehhez a meccshez. Ez az eredmény és az utána bevitt összes eredmény törlődik. A bajnokság innen folytatható.','Visszalépés'))return;const next=clone(state);next.events=next.events.slice(0,index);persist(next);view='play';detail=null;render();window.scrollTo({top:0,behavior:'smooth'});}
 function downloadJSON(data,filename){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function download(){if(!state)return;downloadJSON(state,'autos-bl-mentes-'+new Date().toISOString().slice(0,10)+'.json');toast('A bajnokság mentése letöltve.');}
 function downloadHistory(){try{const data=H.load(localStorage);downloadJSON(data,'autos-bl-tornaelozmenyek.json');toast('Az összes torna előzménye letöltve.');}catch(e){toast('Az előzmények nem tölthetők le: '+e.message);}}
 function downloadRoster(){try{const data=R.pack(currentPots());downloadJSON(data,'autos-bl-autolista.json');toast('Az autólista letöltve, a négy kalappal együtt.');}catch(e){toast('Az autólista nem tölthető le: '+e.message);}}
 function summary(){const d=E.derive(state);return 'AUTÓS BAJNOKOK LIGÁJA\nSorsolás azonosítója: '+state.seed+'\nSzakasz: '+d.current.name+'\nLejátszott meccsek: '+state.events.filter(e=>e.type==='win').length+'\n'+(d.match?'Következő: '+byId(d.match.a).name+' – '+byId(d.match.b).name+(d.current.need>1?' ('+d.match.wins.filter(w=>w===d.match.a).length+'–'+d.match.wins.filter(w=>w===d.match.b).length+', '+d.current.need+' győzelemig)':''):'A szakasz kész.')+(d.champion?'\nBajnok: '+byId(d.champion).name:'')+'\n\nTABELLA\nHely | Autó | Kalap | M | Gy | V | Pont | Ellenfélpont | Legyőzöttpont | Sorshely\n'+d.table.map(c=>[c.rank,c.name,c.pot,c.played,c.won,c.lost,c.points,c.sos,c.sov,c.lot+1].join(' | ')).join('\n')+'\n\nTELJES VERSENYÁLLÁS (folytatáshoz és ellenőrzéshez)\n'+JSON.stringify(state);}
 $('toolsButton').onclick=()=>{const open=$('tools').hidden;$('tools').hidden=!open;$('toolsButton').setAttribute('aria-expanded',String(open));};
 $('exportButton').onclick=download;
 $('historyButton').onclick=()=>{view='history';historyEntry=null;historyCar=null;detail=null;render();};
 $('exportHistoryButton').onclick=downloadHistory;
 $('saveRosterButton').onclick=saveRoster;
 $('exportRosterButton').onclick=downloadRoster;
 $('copyButton').onclick=async()=>{if(!state)return;const text=summary();try{await navigator.clipboard.writeText(text);toast('Kimásolva. Beillesztheted a chatbe.');}catch(e){$('summaryText').value=text;$('summaryDialog').showModal();$('summaryText').select();}};
 $('summaryClose').onclick=()=>$('summaryDialog').close();
 async function newTournament(pots){const completed=state&&E.derive(state).champion;if(state&&!await ask('Új bajnokság',completed?'A lezárt tornát elmentjük az Előzmények közé. A 32 autó és a kalapbeosztás megmarad az új bajnokságra.':'A jelenlegi játék helyére új bajnokság kerül. Ha meg szeretnéd őrizni, előbb töltsd le a mentését. A 32 autó és a kalapbeosztás megmarad, újragépelés nélkül.','Új bajnokság'))return;try{if(completed){H.save(localStorage,state,archiveTitle());historyRaw=undefined;}const data=R.save(localStorage,pots);localStorage.setItem(DRAFT,JSON.stringify(data.pots));localStorage.removeItem(KEY);}catch(e){toast('Nem sikerült előkészíteni az új bajnokságot: '+e.message);return;}state=null;view='play';detail=null;render();window.scrollTo({top:0,behavior:'smooth'});}
 $('newButton').onclick=()=>newTournament(currentPots());
 $('importFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>12000000)throw Error('Ez a mentés túl nagy.');const raw=JSON.parse(await file.text());if(raw?.kind===H.KIND){const added=H.merge(localStorage,raw);if(!state&&!savedRoster()){const latest=H.load(localStorage).tournaments.slice().sort((a,b)=>Date.parse(b.savedAt)-Date.parse(a.savedAt))[0];if(latest){const roster=R.fromTournament(latest.state);R.save(localStorage,roster.pots);localStorage.setItem(DRAFT,JSON.stringify(roster.pots));}}historyRaw=undefined;view='history';historyEntry=null;historyCar=null;detail=null;render();toast('Előzmények betöltve. '+added+' új torna hozzáadva.');return;}if(raw.kind==='autos-bl-autolista'){const roster=R.validate(raw);await newTournament(roster.pots);return;}const imported=E.validate(raw);if(state&&!await ask('Mentés betöltése','A jelenlegi játék helyére a kiválasztott mentés kerül.','Betöltés'))return;persist(imported);view='play';detail=null;render();toast('Mentés betöltve. Folytathatjátok a játékot.');}catch(err){toast('Nem sikerült betölteni: '+err.message);}};
 window.addEventListener('storage',e=>{if(e.key===H.KEY){historyRaw=undefined;if(view==='history'||state)render();return;}if(e.key!==KEY&&e.key!==null)return;try{state=e.newValue?E.validate(JSON.parse(e.newValue)):null;detail=null;view='play';busy=false;render();toast(state?'A játékállás másik lapról frissült.':'A másik lapon új bajnokságot készítetek elő. Az autólista megmaradt.');}catch(err){toast('A másik lap mentése nem tölthető be. A jelenlegi játékot megtartottuk.');}});
 if(state&&!savedRoster())try{R.save(localStorage,R.fromTournament(state).pots);}catch(e){}
 render();
})();
